import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";



// MSW는 비동기로 시작 + 타임아웃 + 경로 폴백
async function startMSWithFallbacks() {
  const tries = [
    { url: `${firstBase() }mockServiceWorker.js`, scope: firstBase() },
    { url: `${pathBase() }mockServiceWorker.js`,  scope: pathBase()  },
    { url: `/mockServiceWorker.js`,               scope: `/`         },
  ];
  for (const sw of tries) {
    try {
      await withTimeout(
        worker.start({ serviceWorker: sw, onUnhandledRequest: "bypass" }),
        2500
      );
      console.log("[MSW] registered:", sw.url);
      return true;
    } catch (e) {
      console.warn("[MSW] register failed:", sw.url, e);
    }
  }
  return false;
}

async function bootstrap() {
  await startMSWithFallbacks(); // 성공/실패와 상관없이 렌더는 진행

  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );   
}
bootstrap();

// 가장 먼저 사용할 베이스: PUBLIC_URL 또는 BASE_URL
function firstBase() {
  const viteBase = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.BASE_URL) || "";
  const craBase  = (typeof process !== "undefined" && process.env && process.env.PUBLIC_URL) || "";
  const picked = craBase || viteBase || "/";
  return picked.endsWith("/") ? picked : picked + "/";
}
// 현재 URL 기준 첫 세그먼트(/woodenpages/)를 베이스로 추정
function pathBase() {
  const p = (typeof window !== "undefined" && window.location && window.location.pathname) || "/";
  const seg = p.split("/").filter(Boolean)[0];
  const b = seg ? `/${seg}/` : "/";
  return b;
}
function withTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise((_, rej) => setTimeout(() => rej(new Error("sw-timeout")), ms)),
  ]);
}
